      "type": "boolean"
    },
    "vendor": {
      "default": "",
      "description": "Name of the seller, vendor, or store",
      "title": "Vendor",
      "type": "string"
    },
    "invoice_date": {
      "default": "",
      "description": "Invoice date in YYYY-MM-DD or readable date format",
      "title": "Invoice Date",
      "type": "string"
    },
    "line_items": {
      "description": "List of line items on the invoice",
      "items": {
        "$ref": "#/$defs/LineItem"
      },
      "title": "Line Items",
      "type": "array"
    },
    "currency": {
      "default": "USD",
      "description": "Currency symbol or code as stated in the invoice (e.g. 'Rs', 'PKR', 'USD', '$', 'EUR', 'GBP').",
      "title": "Currency",
      "type": "string"
    },
    "subtotal": {
      "default": 0.0,
      "description": "Sum of line item totals before tax",
      "title": "Subtotal",
      "type": "number"
    },
    "tax": {
      "default": 0.0,
      "description": "Tax amount applied to invoice",
      "title": "Tax",
      "type": "number"
    },
    "total_amount": {
      "default": 0.0,
      "description": "Final payable amount",
      "title": "Total Amount",
      "type": "number"
    }
  },
  "title": "Invoice",
  "type": "object"
}

